"""Pydantic v2 schemas for structured conversation summaries."""

from datetime import datetime
from typing import Any
from pydantic import BaseModel, ConfigDict, Field


class GeminiSummaryExtraction(BaseModel):
    """Structured JSON fields generated by Gemini from conversation history."""

    conversation_title: str = "Sales Conversation Summary"
    summary: str = ""
    main_business_problem: str | None = None
    customer_requirements: list[str] = Field(default_factory=list)
    pain_points: list[str] = Field(default_factory=list)
    discussed_products: list[str] = Field(default_factory=list)
    objections: list[str] = Field(default_factory=list)
    customer_questions: list[str] = Field(default_factory=list)
    unresolved_questions: list[str] = Field(default_factory=list)
    recommended_next_action: str = "Review conversation and follow up as appropriate."


class SummaryGenerateRequest(BaseModel):
    is_completed: bool = False


class ConversationSummarySchema(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    session_id: str
    lead_id: int
    conversation_title: str
    summary: str
    customer_name: str | None = None
    company_name: str | None = None
    business_type: str | None = None
    budget: str | None = None
    purchase_timeline: str | None = None
    main_business_problem: str | None = None
    customer_requirements: list[str] = Field(default_factory=list)
    pain_points: list[str] = Field(default_factory=list)
    discussed_products: list[str] = Field(default_factory=list)
    objections: list[str] = Field(default_factory=list)
    customer_questions: list[str] = Field(default_factory=list)
    sentiment_overview: dict[str, Any] = Field(default_factory=dict)
    qualification_status: str
    appointment_reference: str | None = None
    unresolved_questions: list[str] = Field(default_factory=list)
    recommended_next_action: str
    is_conversation_completed: bool
    message_count_at_generation: int
    summary_version: int
    generated_at: datetime
    updated_at: datetime


class SummaryListResponse(BaseModel):
    total: int
    limit: int
    offset: int
    items: list[ConversationSummarySchema]
